do $test$
declare kept uuid:=gen_random_uuid(); merged uuid:=gen_random_uuid(); session_id uuid:=gen_random_uuid(); photo uuid:=gen_random_uuid(); booking uuid:=gen_random_uuid(); candidature uuid:=gen_random_uuid();
 actor uuid:='00000000-0000-4000-8000-00000000c0c0'; project uuid:='00000000-0000-4000-8000-0000000070e0'; announcement uuid:='00000000-0000-4000-8000-00000000a000';
begin begin
 insert into public.figurants(id,prenom,nom,date_naissance,acces_compte) values(kept,'Fusion','Gardée','1990-01-01',false),(merged,'Fusion','Source','1990-01-01',true);
 insert into public.figurant_comptes(figurant_id,password_hash) values(merged,'fixture-inutilisable');
 insert into public.candidatures(id,figurant_id,annonce_id,message) values(candidature,merged,announcement,'Message fictif fusion');
 insert into public.bookings(id,figurant_id,projet_id,candidature_id,date,notes) values(booking,merged,project,candidature,current_date+10,'Historique fictif');
 insert into public.figurant_photos(id,figurant_id,type,storage_path) values(photo,merged,'portrait',merged::text||'/fictif.png');
 insert into public.figurant_liens(figurant_id,label,url) values(merged,'Démo','https://example.test/demo');
 insert into public.figurant_messages(figurant_id,projet_id,sender,corps) values(merged,project,'staff','Message privé fictif');
 insert into public.figurant_sessions(figurant_id,token,expires_at) values(merged,gen_random_uuid()::text,now()+interval '1 hour');
 insert into public.figurant_auth_tokens(figurant_id,token,expires_at,objet) values(merged,gen_random_uuid()::text,now()+interval '1 hour','connexion');
 insert into auth.sessions(id,user_id,created_at) values(session_id,actor,now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated','session_id',session_id)::text,true);
 execute format('create function pg_temp.fail_merge_fixture() returns trigger language plpgsql as $guard$ begin if old.figurant_id=%L::uuid then raise exception using errcode=''ZX003'',message=''fixture panne photo''; end if; return new; end $guard$',merged::text);
 create trigger fixture_merge_failure before update on public.figurant_photos for each row execute function pg_temp.fail_merge_fixture();
 set local role authenticated;
 begin perform public.merge_figurants_atomique(kept,merged); raise exception using errcode='ZX002',message='Panne intermédiaire ignorée'; exception when sqlstate 'ZX003' then null; end;
 reset role;
 assert exists(select 1 from public.figurants where id=merged),'Profil source perdu après panne';
 assert (select not acces_compte from public.figurants where id=kept),'Accès cible partiellement activé';
 assert (select figurant_id=merged from public.candidatures where id=candidature),'Candidature déplacée malgré rollback';
 assert (select figurant_id=merged from public.bookings where id=booking),'Booking déplacé malgré rollback';
 assert exists(select 1 from public.figurant_comptes where figurant_id=merged),'Compte déplacé malgré rollback';
 assert not exists(select 1 from public.figurant_comptes where figurant_id=kept),'Compte cible créé malgré rollback';
 assert (select count(*)=1 from public.figurant_sessions where figurant_id=merged),'Session supprimée malgré rollback';
 assert (select count(*)=1 from public.figurant_auth_tokens where figurant_id=merged),'Lien supprimé malgré rollback';
 drop trigger fixture_merge_failure on public.figurant_photos;
 set local role authenticated;
 perform public.merge_figurants_atomique(kept,merged);
 reset role;
 assert not exists(select 1 from public.figurant_sessions where figurant_id in(kept,merged)),'Session ancienne transférée';
 assert not exists(select 1 from public.figurant_auth_tokens where figurant_id in(kept,merged)),'Lien ancien transféré';
 assert not exists(select 1 from public.figurants where id=merged),'Source non supprimée';
 assert (select acces_compte from public.figurants where id=kept),'Accès non repris';
 assert exists(select 1 from public.figurant_comptes where figurant_id=kept),'Compte non repris';
 assert (select figurant_id=kept from public.candidatures where id=candidature),'Candidature non reprise';
 assert (select figurant_id=kept from public.bookings where id=booking),'Booking non repris';
 assert (select figurant_id=kept from public.figurant_photos where id=photo),'Photo non reprise';
 assert exists(select 1 from public.figurant_messages where figurant_id=kept and corps='Message privé fictif'),'Message non repris';
 assert exists(select 1 from public.figurant_liens where figurant_id=kept),'Lien non repris';
 -- Deux comptes déjà actifs : aucun écrasement de mot de passe ni transfert partiel.
 insert into public.figurants(id,prenom,nom,date_naissance,acces_compte) values(merged,'Fusion','Conflit','1990-01-01',true);
 insert into public.figurant_comptes(figurant_id,password_hash) values(merged,'second-fixture');
 insert into public.candidatures(figurant_id,annonce_id,message) values(merged,announcement,'Candidature en conflit fictive');
 set local role authenticated;
 begin perform public.merge_figurants_atomique(kept,merged); raise exception using errcode='ZX002',message='Conflit accepté'; exception when unique_violation then null; end;
 reset role;
 assert exists(select 1 from public.figurants where id=merged),'Profil perdu après conflit';
 assert exists(select 1 from public.candidatures where figurant_id=merged and annonce_id=announcement),'Candidature conflictuelle perdue';
 assert (select password_hash='second-fixture' from public.figurant_comptes where figurant_id=merged),'Mot de passe déplacé après conflit';
 insert into public.minor_dossiers(projet_id,figurant_id) values(project,kept);
 set local role authenticated;
 begin perform public.merge_figurants_atomique(kept,merged); raise exception using errcode='ZX002',message='Dossier légal déplacé sans revue'; exception when check_violation then null; end;
 reset role;
 assert exists(select 1 from public.minor_dossiers where figurant_id=kept),'Dossier légal modifié';
 assert exists(select 1 from public.figurants where id=merged),'Profil perdu après refus légal';
 raise exception using errcode='ZX001',message='rollback fixtures';
 exception when sqlstate 'ZX001' then null; end;
end $test$;
